from collections import Counter

def transform(grid):
    h,w=len(grid),len(grid[0]); out=[[7]*w for _ in range(h)]
    rc=Counter(tuple(row) for row in grid).most_common(1)[0]
    cc=Counter(tuple(grid[r][c] for r in range(h)) for c in range(w)).most_common(1)[0]
    vertical=rc[1]>=cc[1]
    if vertical:
        common,count=rc; band=[r for r,row in enumerate(grid) if tuple(row)==common]
        if band[-1]==h-1: k=min(band); coords=list(range(k)); d=h-k
        else: k=max(band); coords=list(range(k+1,h)); d=-min(coords)
        pattern=[(r,c) for r in coords for c in range(w)]
    else:
        common,count=cc; band=[c for c in range(w) if tuple(grid[r][c] for r in range(h))==common]
        if band[-1]==w-1: k=min(band); coords=list(range(k)); d=w-k
        else: k=max(band); coords=list(range(k+1,w)); d=-min(coords)
        pattern=[(r,c) for r in range(h) for c in coords]
    for r,c in pattern:
        if grid[r][c]==9 and any(grid[rr][cc]==7 for rr,cc in ([(rr,c) for rr in range(h) if rr not in coords] if vertical else [(r,cc) for cc in range(w) if cc not in coords])): out[r][c]=9
    for r,c in pattern:
        if grid[r][c]!=7 and out[r][c]!=9:
            rr=r+(d if vertical else 0); cc=c+(0 if vertical else d)
            out[rr][cc]=grid[r][c]
    return out

